import {
  Body,
  Controller,
  Get,
  HttpException,
  HttpStatus,
  InternalServerErrorException,
  NotFoundException,
  Param,
  Post,
  Res,
  UseFilters,
} from '@nestjs/common';

import { ApiOkResponse, ApiOperation, ApiParam } from '@nestjs/swagger';
import { Response } from 'express';
// Import { Response } from 'express';
import { AlertService } from './alert.service';
import { SfgClosedMessage } from './dto/sfg-closed-messege-dto';
import { WorkcentersResponseDTO } from './dto/workcenter.dto';
import { WriteBackCloseAlertResponse } from './dto/write-back-close-alert-response-dto';
import { MesGenericErrorFilter } from '@/common/filters/mes-generic-error.filter';
import { WriteBackResponse } from '@/picking/dto/write-back-response-dto';
// The starting endpoint of the picking module

@Controller('alert')
export class AlertController {
  public constructor(private readonly alertService: AlertService) {}

  @ApiOperation({
    description:
      'This endpoint lets you retrieve the data of a single shop order in a specific plant using the shoprOrderId and plantCode passed as a parameters.',

    summary: 'Get a specific shopOrder in a specific plant',
  })
  @ApiParam({
    example: '1146',
    name: 'plantCode',
    required: true,
    type: 'number',
  })
  @Post('automaticCloseAlert/:plant')
  public async closeAutomaticAlert(
    @Param('plant') plant: number,
  ): Promise<WriteBackCloseAlertResponse> {
    try {
      const result = await this.alertService.closeAutomaticAlert(plant);
      return result;
    } catch (error) {
      if (error.message.includes('404')) {
        throw new HttpException('Resource not found', HttpStatus.NOT_FOUND);
      } else if (error.message.includes('500')) {
        throw new HttpException(
          'Internal Server Error',
          HttpStatus.INTERNAL_SERVER_ERROR,
        );
      } else {
        throw new HttpException(
          'Unexpected error occurred',
          HttpStatus.INTERNAL_SERVER_ERROR,
        );
      }
    }
  }

  @Post('checkForAlertEscalation/:plant')
  @UseFilters(MesGenericErrorFilter)
  public async escalateAlert(
    @Param('plant') plant: number,
  ): Promise<WriteBackResponse | undefined> {
    try {
      const result = await this.alertService.escalateAlert(plant);
      return result;
    } catch (error) {
      if (error.message.includes('404')) {
        throw new HttpException('Resource not found', HttpStatus.NOT_FOUND);
      } else if (error.message.includes('500')) {
        throw new HttpException(
          'Internal Server Error',
          HttpStatus.INTERNAL_SERVER_ERROR,
        );
      } else {
        throw new HttpException(
          'Unexpected error occurred',
          HttpStatus.INTERNAL_SERVER_ERROR,
        );
      }
    }
  }

  @ApiOperation({
    description: 'This API is designed to get all workcenters in the plant ',
    summary: 'Get all workcenters details by plant',
  })
  @ApiOkResponse({
    description: 'workcenter details',
  })
  @ApiParam({
    example: '1237',
    name: 'plantKey',
    required: true,
    type: Number,
  })
  @Get('/GetAllWorkcenters/:plantKey')
  public async getAllWorkcenters(
    @Param('plantKey') plantKey: number,
  ): Promise<Array<WorkcentersResponseDTO>> {
    try {
      const result = await this.alertService.getWorkcentersByPlant(plantKey);
      return result;
    } catch (error) {
      const errorNotFoundException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve workcenters',
              error,
            );
      throw errorNotFoundException;
    }
  }

  @Post('/automaticAlertCreation/:plantKey')
  @UseFilters(MesGenericErrorFilter)
  public async automaticAlertCreation(
    @Param('plantKey') plantKey: number,
    @Res() response: Response,
  ): Promise<Response> {
    const result = await this.alertService.automaticAlertCreation(plantKey);
    return response.json(result);
  }

  @Post('sfg-closed-event')
  public handleSfgClosedEvent(@Body() data: SfgClosedMessage): void {
    this.alertService.handleSfgClosedEvent(data);
  }
}

