@Injectable()
export class AlertRepository {
  private readonly logger = new AppLogger();

  private readonly customHttpService: HttpService;

  private readonly client: CosmosClient;

  private readonly database;

  private readonly container;

  public constructor(
    private readonly httpService: HttpService,
    private readonly orderApi: OrderApi,
    private readonly plantHYRApi: PlantHierarchyApi,
    private readonly cosmosConfigService: CosmosDatabaseConfigService,
    private readonly apiManagerConfigService: ApiManagerConfigService,
    private readonly pickingService: PickingService,
    private readonly shipmentApi: ShipmentApi,
  ) {
    const credential = new DefaultAzureCredential();

    this.client = new CosmosClient({
      aadCredentials: credential,
      endpoint: this.cosmosConfigService.cosmosDbEndpoint,
    });

    this.database = this.client.database(
      this.cosmosConfigService.cosmosDbDatabase,
    );
    this.container = this.database.container(
      this.cosmosConfigService.cosmosDbContainer,
    );
    const httpsAgent = new https.Agent({
      rejectUnauthorized: true, // Enforce SSL Certificate Verification
    });

    // Create a custom Axios instance using the custom HTTPS agent
    const axiosConfig: AxiosRequestConfig = {
      headers: this.httpService.axiosRef.defaults.headers as object, // Ensure headers are properly typed
      httpsAgent,
    };

    const customAxiosInstance = axios.create(axiosConfig);

    // Initialize a new HttpService with the custom Axios instance
    this.customHttpService = new HttpService(customAxiosInstance);
  }

  public async createReschedulerWkHistory(
    payload: AddReschedulerWkHistoryDTO,
  ): Promise<Array<WriteBackResponse> | undefined> {
    const daprClient = new DaprClient();
    const parsedDate = new Date(payload.newPickingTime);
    if (Number.isNaN(parsedDate.getTime())) {
      throw new TypeError(`Invalid date format: ${payload.newPickingTime}`);
    }

    try {
      if (payload.range) {
        const requesDto = new OrdersByRangeDTO();
        requesDto.plant = payload.plant;
        requesDto.workcenter = payload.workcenter;
        requesDto.range = payload.range;
        requesDto.startPickingTime = payload.alertCreationTime;

        const shopOrders =
          await this.orderApi.fetchOrderToBeRescheduledByRange(requesDto);
        const alertCreationDate = new Date(payload.alertCreationTime);
        const newPickingDate = new Date(payload.newPickingTime);

        const hourOfRescheduling: number =
          newPickingDate.getTime() - alertCreationDate.getTime();

        const allResults: Array<WriteBackResponse> = [];

        if (shopOrders.length > 0) {
          await ChunkProcess.processInChunksArray(
            shopOrders,
            100, // Chunk size
            async (chunk) => {
              const rescheduledShopOrders: Array<ReschedulerWkHistoryInMassDTO> =
                chunk.map((so) => ({
                  alertCreationTime: so.plannedStartDate,
                  comment: payload.comment ?? undefined,
                  oldPickingTime: so.plannedStartDate,
                  pickingOrderId: so.pickingOrderId,
                  reasonId: payload.reasonId,
                }));

              const result = await this.createReschedulingInMass(
                payload.plant,
                hourOfRescheduling,
                rescheduledShopOrders,
              );

              if (result) {
                if (Array.isArray(result)) {
                  allResults.push(...result);
                } else {
                  allResults.push(result);
                }
              }

              // Always return an array to satisfy TypeScript
              return result ?? [];
            },
            undefined,
            5,
          );
        }

        return allResults.length > 0 ? allResults : undefined;
      }
      // Single rescheduling without range
      const formattedDate = parsedDate.toISOString();
      const newPayload = {
        alertCreationTime: payload.alertCreationTime,
        comment: payload.comment ?? undefined,
        newPickingTime: formattedDate,
        oldPickingTime: payload.oldPickingTime,
        pickingOrderId: payload.pickingOrderId,
        plant: payload.plant,
        reasonId: payload.reasonId,
      };
      const token = `Bearer ${process.env.TOKEN}`;
      const options = { headers: { authorization: token } };
      await daprClient.invoker.invoke(
        this.apiManagerConfigService.orderApiAppId,
        `rescheduler-wk-history/add`,
        HttpMethod.POST,
        structuredClone(newPayload),
        options,
      );

      const parameters = new WriteBackParameters();
      parameters.inPlant = String(payload.plant);
      parameters.inShopOrder = payload.pickingOrderId;
      parameters.newPromiseTime = formattedDate;

      const response = await this.acknownledgeAlert(parameters);
      return [response];
    } catch (error) {
      this.logger.error('Error invoking Dapr service ORDER:', error);
      return undefined;
    }
  }

  public async acknownledgeAlert(
    writeBackParameters: WriteBackParameters,
  ): Promise<WriteBackResponse> {
    const {
      inShopOrder: shopOrderId,
      inPlant: plantKey,
      newPromiseTime,
    } = writeBackParameters;

    const daprClient = new DaprClient();
    const lockDateTime = new Date().toISOString();
    const { daprSecretStore } = this.apiManagerConfigService;
    const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
    const { mesPasswordSecretName } = this.apiManagerConfigService;
    const apiMgrKeyObject = await daprClient.secret.get(
      daprSecretStore,
      apiMgrKeySecretName,
    );
    const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];
    const mesPasswordObject = await daprClient.secret.get(
      daprSecretStore,
      mesPasswordSecretName,
    );
    const mesPasswordValue = Object.values(mesPasswordObject)[0];
    const plantLinkBaseUrl = await this.plantHYRApi.getPlantLink(
      Number(plantKey),
    );
    const isApiManagerEnabled =
      await this.apiManagerConfigService.apiManagerEnabled(); // Convert the env variable to boolean since its a string

    const mesUserName = await this.apiManagerConfigService.mesUserName();
    const shopOrderResponse =
      await this.pickingService.getPickingByPlantIdAndShopOrderId(
        plantKey,
        shopOrderId,
      );
    let shopOrder = shopOrderResponse.shopOrderList as ShopOrder;
    if (shopOrder.alertCreated) {
      if (shopOrder) {
        shopOrder = {
          ...shopOrder,
          lockAction: 'RESCH',
          lockDateTime,
          lockList: ['CREATE_ALERT', 'CLOSE_SO', 'RESCH', 'CLOSE_ALERT'],
        };
      }
      await this.pickingService.create(plantKey, shopOrder);

      const alert = await this.orderApi.getAlertByPlantAndWKNotClosed(
        Number(plantKey),
        shopOrderId,
      );
      const alertParameters = new AlertByIdAndWKParameterDto();
      alertParameters.plant = Number(plantKey);
      alertParameters.pickingOrderId = shopOrderId;
      alertParameters.alertId = alert.alertId;
      const result =
        await this.orderApi.updateAlertRescheduleStatus(alertParameters);
      if (!result) {
        this.logger.error('an error is occured while updating alert status');
      }

      const queryParameters = new URLSearchParams();
      queryParameters.append('service', 'CombineQuery');
      queryParameters.append(
        'queryTemplate',
        'SC_MES_API/INTERFACE/ALERT/V1/UPDATE_ALERT_STATUS_BY_ALERT_ID_PLANT_WK',
      );
      queryParameters.append('InPlant', plantKey);
      queryParameters.append('content-type', 'text/json');
      queryParameters.append('xacuteLoginName', mesUserName);
      queryParameters.append('xacuteLoginPassword', mesPasswordValue);
      queryParameters.append('session', 'false');
      queryParameters.append('Param.1', 'Acknowledged');
      queryParameters.append('Param.2', String(alert.alertId));
      queryParameters.append('Param.3', shopOrderId);
      queryParameters.append('Param.4', plantKey);
      queryParameters.append('Param.5', newPromiseTime);
      const writeBackUrl = isApiManagerEnabled
        ? `${await this.apiManagerConfigService.apiManager()}/mii/illuminator/v1`
        : `${plantLinkBaseUrl}/XMII/Illuminator`;
      if (
        isApiManagerEnabled &&
        (!this.apiManagerConfigService.apiManager ||
          !this.apiManagerConfigService.mesUserName)
      ) {
        throw new Error('API Manager setup is incomplete');
      }
      try {
        const response = await firstValueFrom(
          this.customHttpService.post(writeBackUrl, undefined, {
            headers: {
              apiKey: apiMgrKeyValue,
            },
            params: queryParameters,
          }),
        );
        const jsondData = response.data;
        const row = jsondData?.Rowsets?.Rowset[0]?.Row[0];
        if (!row) {
          shopOrder = {
            ...shopOrder,
            lockAction: '',
            lockDateTime: '',
            lockList: [],
          };

          await this.pickingService.create(plantKey, shopOrder);
          return {
            alertId: 0,
            statusCode: 'FAILURE',
            statusMessage: 'Error in MII',
          };
        }
        const { UPDATED_ROW } = row;

        if (UPDATED_ROW === 0) {
          shopOrder = {
            ...shopOrder,
            lockAction: '',
            lockDateTime: '',
            lockList: [],
          };

          await this.pickingService.create(plantKey, shopOrder);
          return {
            alertId: alert.alertId,
            statusCode: 'FAILURE',
            statusMessage: 'NO_UPDATES',
          };
        }
        return {
          alertId: alert.alertId,
          statusCode: 'SUCCESS',
          statusMessage: 'UPDATED_SUCCESSFULY',
        };
      } catch (error) {
        shopOrder = {
          ...shopOrder,
          lockAction: '',
          lockDateTime: '',
          lockList: [],
        };

        await this.pickingService.create(plantKey, shopOrder);
        if (error.response) {
          // Handle HTTP errors
          switch (error.response.status) {
            case 404: {
              this.logger.error(
                `Resource not found (404). URL: ${error.config.url}`,
              );
              throw new Error('Resource not found (404)');
            }
            case 500: {
              this.logger.error(
                `Internal Server Error (500). URL: ${error.config.url}`,
              );
              throw new Error('Internal Server Error (500)');
            }
            default: {
              this.logger.error(
                `Unexpected HTTP error: ${error.response.status}. URL: ${error.config.url}`,
              );
              throw new Error(
                `Unexpected error occurred: ${error.response.status}`,
              );
            }
          }
        } else {
          this.logger.error('An unexpected error occurred', error);
          throw new Error('An unexpected error occurred');
        }
      }
    } else {
      this.logger.error(
        'An unexpected error occurred: there is no alert created for this WK',
      );
      return {
        alertId: 0,
        statusCode: 'SUCCESS',
        statusMessage: 'NO ALERT FOUND FOR THIS WK',
      };
    }
  }

  public async createReschedulingInMass(
    plant: number,
    range: number,
    rescheduledShopOrders: Array<ReschedulerWkHistoryInMassDTO>,
  ): Promise<Array<WriteBackResponse> | undefined> {
    try {
      const responses: Array<WriteBackResponse> = [];
      const parameters = new WriteBackParameters();
      parameters.inPlant = String(plant);
      const shopOrders = await this.orderApi.rescheduleWkHistoryInMass(
        plant,
        range,
        rescheduledShopOrders,
      );
      if (shopOrders.length > 0) {
        for (const order of shopOrders) {
          parameters.inShopOrder = order.pickingOrderId;
          parameters.newPromiseTime = String(order.newPickingTime);
          const result = await this.acknownledgeAlert(parameters);
          responses.push(result);
        }
      }
      return responses;
    } catch (error) {
      this.logger.error('Error in Rescheduling in MASS :', error);
      return undefined;
    }
  }
}

import * as https from 'node:https';
