  public async getWorkcentersByPlant(
    plantKey: number,
  ): Promise<Array<WorkcentersResponseDTO>> {
    const alertStatus = ['OPEN', 'Non-Acknowledged'];

    // Initialize query parts and parameters
    let whereClause = `WHERE c.plant = @partitionKeyValue`;
    const parameters: Array<AlertQueryParameter> = [
      { name: '@partitionKeyValue', value: Number(plantKey) },
    ];
    whereClause += ` AND ARRAY_CONTAINS(@alertStatus, c.alertStatus)`;
    parameters.push({ name: '@alertStatus', value: alertStatus });

    // Construct the final query with the dynamic WHERE clause
    const querySpec = {
      parameters,
      query: `
        SELECT DISTINCT c.workcenter FROM c
        ${whereClause}
      `,
    };

    try {
      const { resources } = await this.container.items
        .query(querySpec)
        .fetchAll();

      if (!resources || resources.length === 0) {
        throw new HttpException(`No data found for this plant `, 404);
      }
      return resources;
    } catch (error) {
      this.logger.error(
        `Error fetching data from Cosmos DB for plant ${plantKey}: ${error}`,
      );
      throw new HttpException('Internal Server Error', 500);
    }
  }

  public async closeAutomaticAlert(
    plant: number,
  ): Promise<WriteBackCloseAlertResponse> {
    try {
      const daprClient = new DaprClient();
      const { daprSecretStore } = this.apiManagerConfigService;
      const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
      const { mesPasswordSecretName } = this.apiManagerConfigService;
      const apiMgrKeyObject = await daprClient.secret.get(
        daprSecretStore,
        apiMgrKeySecretName,
      );
      const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];
      const mesPasswordObject = await daprClient.secret.get(
        daprSecretStore,
        mesPasswordSecretName,
      );
      const mesPasswordValue = Object.values(mesPasswordObject)[0];
      const plantLinkBaseUrl = await this.plantHYRApi.getPlantLink(
        Number(plant),
      );

      const isApiManagerEnabled =
        await this.apiManagerConfigService.apiManagerEnabled(); // Convert the env variable to boolean since its a string

      const mesUserName = await this.apiManagerConfigService.mesUserName();
      const alertsLinkedToCloseWks =
        await this.orderApi.getAlertListLinkedToCloseWKs(plant);
      const alertsWithReschedulerCheck =
        await this.orderApi.getAlertListWithReschedulerCheck(plant);
      let alerts = [...alertsLinkedToCloseWks, ...alertsWithReschedulerCheck];
      alerts = alerts.slice(0, 200);
      const queryParameters = new URLSearchParams();
      queryParameters.append('service', 'CombineQuery');
      queryParameters.append(
        'queryTemplate',
        'SC_MES_API/INTERFACE/ALERT/V1/CLOSE_ALERT_BY_ALERT_ID_PLANT',
      );
      queryParameters.append('inPlant', String(plant));
      queryParameters.append('content-type', 'text/json');
      queryParameters.append('xacuteLoginName', mesUserName);
      queryParameters.append('xacuteLoginPassword', mesPasswordValue);
      queryParameters.append('session', 'false');
      const writeBackUrl = isApiManagerEnabled
        ? `${await this.apiManagerConfigService.apiManager()}/mii/illuminator/v1`
        : `${plantLinkBaseUrl}/XMII/Illuminator`;
      if (
        isApiManagerEnabled &&
        (!this.apiManagerConfigService.apiManager ||
          !this.apiManagerConfigService.mesUserName)
      ) {
        await this.storedLogger.functionalLog(
          {
            applicationName: 'picking-be',
            errorCode: ERROR_CODES.incompleteApiManager.code,
            objectId: `${plant}`,
            plant,
            user: 'SYSTEM-JOB',
          },
          { usefireAndForget: true },
        );
        throw new Error('API Manager setup is incomplete');
      }
      let statusCode;
      let statusMessage;
      let updatedRow;
      if (!alerts || alerts.length === 0) {
        statusCode = 'FAILURE';
        statusMessage = 'No Alerts to be closed';
        updatedRow = 0;
      }
      // Helper function to split array into chunks
      const alertIds = alerts.map((alert) => alert.alertId);

      const requestBody = {
        alerts: alertIds.join(','), // Pass the alertIds as an array in the body
        plant, // Send the plant as a parameter
      };
      // Call API to update status for the current batch

      const formData = new URLSearchParams();
      formData.append('Param.1', JSON.stringify(requestBody));
      const headersDto = new RequestHeadersDto(
        'application/x-www-form-urlencoded', // ContentType
        apiMgrKeyValue, // ApiKey
      );
      const response = await firstValueFrom(
        this.customHttpService.post(writeBackUrl, formData, {
          headers: { ...headersDto },
          maxBodyLength: Infinity,
          maxContentLength: Infinity,
          params: queryParameters,
        }),
      );
      const jsondData = response.data;
      const row = jsondData?.Rowsets?.Rowset[0]?.Row[0];
      if (!row) {
        statusCode = 'FAILURE';
        statusMessage = 'Error in MII';
        updatedRow = 0;
      }
      const { UPDATED_ROW } = row;
      if (UPDATED_ROW >= 0) {
        statusCode = 'SUCCESS';
        updatedRow = UPDATED_ROW;
        statusMessage =
          UPDATED_ROW === 0 ? 'No row updated' : 'Updated Successfuly';
      }
      const writeBackMessage = new WriteBackCloseAlertResponse();
      writeBackMessage.statusCode = String(statusCode);
      writeBackMessage.statusMessage = String(statusMessage);
      writeBackMessage.updatedRow = Number(updatedRow);
      if (writeBackMessage.statusCode === 'SUCCESS') {
        // Get unique pickingOrderIds
        const uniquePickingOrderIds = [
          ...new Set(alertsWithReschedulerCheck.map((a) => a.pickingOrderId)),
        ];

        if (uniquePickingOrderIds.length > 0) {
          // Check which pickingOrderIds already have comments
          const commentExistResults = await this.orderApi.doesCommentExist(
            Number(plant),
            uniquePickingOrderIds,
          );

          // Filter pickingOrderIds where comment does NOT exist
          const pickingOrderIdsWithoutComments = commentExistResults
            .filter((r) => !r.exist)
            .map((r) => r.pickingOrderId);

          // Build only the new comments
          const commentDtos: Array<CreatePickingOrderCommentDto> =
            pickingOrderIdsWithoutComments.map((pickingOrderId) => ({
              comment:
                'Alert is closed automatically, WK rescheduled with new Picking Time.',
              userId: 0,
              plant: Number(plant),
              pickingOrderId,
            }));

          await Promise.all(
            commentDtos.map(async (dto) => {
              try {
                await this.orderApi.createComment(dto);
              } catch (error) {
                this.logger.error(
                  `Failed to create comment by the system for PickingOrderId ${dto.pickingOrderId}`,
                  error,
                );
              }
            }),
          );
        }
      }

      return writeBackMessage;
    } catch (error) {
      if (error.response) {
        // Handle HTTP errors
        switch (error.response.status) {
          case 404: {
            this.logger.error(
              `Resource not found (404). URL: ${error.config.url}`,
            );
            throw new Error('Resource not found (404)');
          }
          case 500: {
            this.logger.error(
              `Internal Server Error (500). URL: ${error.config.url}`,
            );
            throw new Error('Internal Server Error (500)');
          }
          default: {
            this.logger.error(
              `Unexpected HTTP error: ${error.response.status}. URL: ${error.config.url} closeAutomaticAlert`,
            );
            throw new Error(
              `Unexpected error occurred: ${error.response.status}`,
            );
          }
        }
      } else {
        await this.storedLogger.functionalLog({
          applicationName: 'picking-be',
          context: {
            method: 'closeAutomaticAlert',
            error,
          },
          errorCode: ERROR_CODES.unexpectedError.code,
          objectId: `${plant}`,
          plant,
          user: 'SYSTEM-JOB',
        });
        throw new Error('An unexpected error occurred');
      }
    }
  }

  public async escalateAlert(
    plantKey: number,
  ): Promise<WriteBackResponse | undefined> {
    const daprClient = new DaprClient();
    const { daprSecretStore } = this.apiManagerConfigService;
    const apiMgrKeySecretName = this.apiManagerConfigService.apiMgrSecretName;
    const { mesPasswordSecretName } = this.apiManagerConfigService;
    const apiMgrKeyValue = await AlertService.getSecretValue(
      daprClient,
      daprSecretStore,
      apiMgrKeySecretName,
    );

    const mesPasswordValue = await AlertService.getSecretValue(
      daprClient,
      daprSecretStore,
      mesPasswordSecretName,
    );
    const plantLinkBaseUrl = await this.plantHYRApi.getPlantLink(
      Number(plantKey),
    );

    const isApiManagerEnabled =
      await this.apiManagerConfigService.apiManagerEnabled(); // Convert the env variable to boolean since its a string

    // If the global variable API_MANAGER_ENABLED is set to true it means
    // We are going to go through api manager else go directly with MII through the plant link coming from PLT HRY Microservice endpoint
    const writeBackUrl = isApiManagerEnabled
      ? `${await this.apiManagerConfigService.apiManager()}/mii/illuminator/v1`
      : `${plantLinkBaseUrl}/XMII/Illuminator`;
    if (
      isApiManagerEnabled &&
      (!this.apiManagerConfigService.apiManager ||
        !this.apiManagerConfigService.mesUserName)
    ) {
      await this.storedLogger.functionalLog(
        {
          applicationName: 'picking-be',
          errorCode: ERROR_CODES.incompleteApiManager.code,
          objectId: `${plantKey}`,
          plant: plantKey,
          user: 'SYSTEM-JOB',
        },
        { usefireAndForget: true },
      );
      throw new Error('API Manager setup is incomplete');
    }

    try {
      const shopOrders = await this.orderApi.fetchAlertToBeEscalated(plantKey);
      const alertsRedBell = await this.orderApi.fetchAlertListForRedBell(
        Number(plantKey),
      );
      const hasShopOrders = Array.isArray(shopOrders) && shopOrders.length > 0;
      const hasRedBell = alertsRedBell && alertsRedBell.trim().length > 0;

      if (!hasShopOrders && !hasRedBell) {
        return {
          statusCode: 'FAILURE',
          statusMessage: 'No alerts to escalate or red bell alerts are empty',
        };
      }

      let shopOrdersXml: string | null = null;
      if (hasShopOrders) {
        const updatedShopOrders =
          await AlertService.processOutboundAndAssignments(
            shopOrders,
            plantKey,
            this.shipmentApi,
          );

        if (updatedShopOrders.length > 0) {
          shopOrdersXml = AlertService.buildShopOrdersXml(updatedShopOrders);
        }
      }

      let alertsRedBellObject = null;
      if (hasRedBell) {
        try {
          alertsRedBellObject = await parseStringPromise(alertsRedBell, {
            explicitArray: false,
          });
        } catch (error) {
          this.logger.error('Failed to parse red bell XML', error);
        }
      }

      let combinedXmlObject = null;

      if (shopOrdersXml && alertsRedBellObject) {
        // Combine both shop orders XML and red bell XML
        const shopOrdersObject = await parseStringPromise(shopOrdersXml, {
          explicitArray: false,
        });

        const shopOrderRows = Array.isArray(
          shopOrdersObject?.Rowsets?.rowset?.row,
        )
          ? shopOrdersObject.Rowsets.rowset.row
          : [shopOrdersObject.Rowsets?.rowset?.row].filter(Boolean);

        const redBellRows = Array.isArray(
          alertsRedBellObject?.Rowsets?.rowset?.row,
        )
          ? alertsRedBellObject.Rowsets.rowset.row
          : [alertsRedBellObject.Rowsets?.rowset?.row].filter(Boolean);

        combinedXmlObject = {
          Rowsets: {
            rowset: {
              row: [...shopOrderRows, ...redBellRows],
            },
          },
        };
      } else if (shopOrdersXml) {
        combinedXmlObject = await parseStringPromise(shopOrdersXml, {
          explicitArray: false,
        });
      } else if (alertsRedBellObject) {
        combinedXmlObject = alertsRedBellObject;
      }

      if (!combinedXmlObject?.Rowsets?.rowset?.row) {
        return {
          statusCode: 'FAILURE',
          statusMessage: 'No alert to escalate',
        };
      }

      const builder = new xml2js.Builder();
      const combinedXmlData = builder.buildObject(combinedXmlObject);
      const parameters = new EscalateAlertRequestDto(
        Number(plantKey),
        'text/xml',
        'ResultXML',
        'SC_MES_API/INTERFACE/ALERT/V1/XCT_ALERT_AUTO_ESCALATE',
        false,
        `${await this.apiManagerConfigService.mesUserName()}`,
        `${mesPasswordValue}`,
      );
      // Form URL encoded data
      const formData = new URLSearchParams();
      formData.append('inAlertEscalation', combinedXmlData);
      const headersDto = new RequestHeadersDto(
        'application/x-www-form-urlencoded', // ContentType
        apiMgrKeyValue, // ApiKey
      );
      const response = await firstValueFrom(
        this.customHttpService.post(writeBackUrl, formData, {
          headers: { ...headersDto },
          maxBodyLength: Infinity,
          maxContentLength: Infinity,
          params: parameters,
        }),
      );
      // Parse XML to JSON
      const jsonData = await parseStringPromise(response.data, {
        explicitArray: false,
      });
      const row = jsonData?.Rowsets?.Rowset?.Row;
      if (!row) {
        return {
          statusCode: 'FAILURE',
          statusMessage: 'Error in MII',
        };
      }
      const { STATUS_CODE: statusCode, STATUS_MESSAGE: statusMessage } = row;

      if (statusCode !== 'SUCCESS') {
        return { statusCode, statusMessage };
      }
      const escalationSummary =
        await AlertService.extractEscalationSummaryFromXml(combinedXmlData);
      await this.orderApi.batchUpdateAlertSmsFlags(escalationSummary);
      return { statusCode, statusMessage };
    } catch (error) {
      await this.storedLogger.functionalLog({
        applicationName: 'picking-be',
        context: {
          method: 'escalateAlert',
          error,
        },
        errorCode: ERROR_CODES.unexpectedError.code,
        objectId: `${plantKey}`,
        plant: plantKey,
        user: 'SYSTEM-JOB',
      });
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException(
          'An unexpected error occurred MII',
        );
      }
      throw error;
    }
  }

