    const { mesPasswordSecretName } = this.apiManagerConfigService;
    const apiMgrKeyObject = await daprClient.secret.get(
      daprSecretStore,
      apiMgrKeySecretName,
    );
    const apiMgrKeyValue = Object.values(apiMgrKeyObject)[0];
    const mesPasswordObject = await daprClient.secret.get(
      daprSecretStore,
      mesPasswordSecretName,
    );
    const mesPasswordValue = Object.values(mesPasswordObject)[0];
    const plantLinkBaseUrl = await this.plantHYRApi.getPlantLink(Number(plant));

    const isApiManagerEnabled =
      await this.apiManagerConfigService.apiManagerEnabled();
    const writeBackUrl = isApiManagerEnabled
      ? `${await this.apiManagerConfigService.apiManager()}/mii/illuminator/v1`
      : `${plantLinkBaseUrl}/XMII/Illuminator`;
    if (
      isApiManagerEnabled &&
      (!this.apiManagerConfigService.apiManager ||
        !this.apiManagerConfigService.mesUserName)
    ) {
      throw new Error('API Manager setup is incomplete');
    }
    this.handleUpdateAlertRequest(
      plant,
      workcenter,
      alertIds,
      apiMgrKeyValue,
      mesPasswordValue,
      writeBackUrl,
    );
  }

  private async handleUpdateAlertRequest(
    plantKey: number,
    workcenter: string,
    alertIds: Array<string>,
    apiMgrKeyValue: string,
    mesPasswordValue: string,
    writeBackUrl: string,
  ): Promise<void> {
    try {
      const headersDto = new RequestHeadersAlertUpdateDto(apiMgrKeyValue);
      const parameters = new AlertUpdateConfig({
        alertIds: alertIds.join(','),
        contentType: 'text/json',
        inPlant: Number(plantKey),
        mesPasswordValue: `${mesPasswordValue}`,
        mesUserName: `${await this.apiManagerConfigService.mesUserName()}`,
        outputParameter: 'ResultXML',
        queryTemplate: 'SC_MES_API/INTERFACE/ALERT/V1/XCT_UPDATE_WC_FOR_SFG_WK',
        session: false,
        workcenter,
      });
      await firstValueFrom(
        this.customHttpService.post(writeBackUrl, undefined, {
          headers: { ...headersDto },
          params: parameters,
        }),
      );
    } catch (error) {
      this.logger.error(
        'An unexpected error occurred MII automatic create alert',
        error,
      );
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException(
          'An unexpected error occurred MII',
        );
      }
      throw error;
    }
  }
}

