// Src/common/filters/http-exception.filter.ts
import {
  Catch,
  HttpException,
  ArgumentsHost,
  HttpStatus,
} from '@nestjs/common';
import { BaseExceptionFilter } from '@nestjs/core';
import { ExceptionResponse } from './interfaces/exception-response.interface';

@Catch(HttpException)
export class MesGenericErrorFilter extends BaseExceptionFilter {
  public static catch(exception: unknown, host: ArgumentsHost): void {
    const context = host.switchToHttp();
    const response = context.getResponse();
    const request = context.getRequest();
    // Determine the status code
    const status =
      exception instanceof HttpException
        ? exception.getStatus()
        : HttpStatus.INTERNAL_SERVER_ERROR;

    let message = 'An error occurred';
    let errorCode = 'UNHANDLED_EXCEPTION';
    if (exception instanceof HttpException) {
      const exceptionResponse = exception.getResponse();
      if (typeof exceptionResponse === 'string') {
        message = exceptionResponse;
      } else if (
        typeof exceptionResponse === 'object' &&
        exceptionResponse !== null
      ) {
        message = (exceptionResponse as ExceptionResponse).message ?? message;
        errorCode = (exceptionResponse as ExceptionResponse).error ?? errorCode;
      }
    } else {
      message = (exception as Error).message || message;
    }

    // Default behavior for other exceptions
    response.status(status).json({
      body: request.body,
      errorCode,
      message,
      params: request.params,
      path: request.url,
      query: request.query,
      statusCode: status,
      timestamp: new Date().toISOString(),
    });
  }
}

import { Logger } from '@nestjs/common';

export class AppLogger extends Logger {
  public log(message: unknown): void {
    super.log(`${new Date().toISOString()} -- ${message}`);
  }

  public error(message: unknown, stack?: string): void {
    super.error(`${new Date().toISOString()} -- ${message}`, stack);
  }

  public warn(message: unknown): void {
