import { CosmosClient, Container } from '@azure/cosmos';
import { DefaultAzureCredential } from '@azure/identity';
import { Injectable, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppLogger } from 'src/common/logger/app-logger';

@Injectable()
export class CosmosDatabaseConfigService implements OnModuleInit {
  private readonly logger = new AppLogger(CosmosDatabaseConfigService.name);

  private readonly client: CosmosClient;

  private readonly container;

  public constructor(private readonly configService: ConfigService) {
    const credential = new DefaultAzureCredential();

    this.client = new CosmosClient({
      aadCredentials: credential,
      endpoint: this.cosmosDbEndpoint,
    });

    // Optionally initialize a container
    this.container = this.client
      .database(this.cosmosDbDatabase)
      .container(this.cosmosDbContainer);
  }

  public get cosmosFunctionalAggregateErrorsByDay(): boolean {
    return (
      this.configService.get<string>('cosmosFunctionalAggregateErrorsByDay') !==
      'false'
    );
  }

  // A method to return the client for reuse in other services
  public get getClient(): CosmosClient {
    return this.client;
  }

  // A method to return the container for reuse in other services
  public get getContainer(): Container {
    return this.container;
  }

  public get cosmosDbEndpoint(): string {
    return (
      this.configService.get<string>('cosmosDbEndpoint') ??
      'https://cosmos-gptmpxn01-eun-dev-core-01.documents.azure.com:443/'
    );
  }

  public get cosmosDbDatabase(): string {
    return this.configService.get<string>('cosmosDbDatabase') ?? 'Mes';
  }

  public get cosmosDbContainer(): string {
    return (
      this.configService.get<string>('cosmosDbContainer') ?? 'PickingOrders'
    );
  }

  public get cosmosDbFunctionalContainer(): string | undefined {
    return (
      this.configService.get<string>('cosmosDbFunctionalContainer') ?? undefined
    );
  }

  public get cosmosFunctionalReplicaId(): string | undefined {
    return (
      this.configService.get<string>('cosmosFunctionalReplicaId') ?? undefined
    );
  }

  public onModuleInit(): void {
    this.checkConfiguration();
  }

  private checkConfiguration(): void {
    // List of required configurations
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined | Container;
    }> = [
      { key: 'container', value: this.container },
      { key: 'cosmosDbDatabase', value: this.cosmosDbDatabase },
      { key: 'cosmosDbEndpoint', value: this.cosmosDbEndpoint },
    ];
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.logger.error(`Missing configuration value for ${config.key}`);
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    this.logger.log(
      `All required configurations  for cosmos container= ${this.cosmosDbContainer}  db= ${this.cosmosDbDatabase} endpoint=${this.cosmosDbEndpoint}are properly set`,
    );
  }
}

